//! Formatting a plain Frame axis value with a Format string, checked against
//! the C library.
//!
//! `axis_format_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/axis_format_probe.c`. C's `AxisFormat` (axis.c:637)
//! rewrites the Format with `ParseAxisFormat`, removing the AST `&` log flag
//! and giving a `.*` precision the Digits value, then hands it to `sprintf`
//! with the value, cast to `int` for an integer conversion. The corpus
//! covers widths, every printf flag, literal text, the integer, character
//! and floating conversions, `%%`, and the log flag.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "axis_format_oracle/cases.rs"]
mod cases;

use ast_core::frames::{BasicFrameBuilder, Frame};

#[test]
fn formats_match_the_c_library() {
    let mut f = BasicFrameBuilder::new(1).build().unwrap();
    Frame::set_digits(&mut f, cases::DIGITS).unwrap();
    let mut failures = Vec::new();
    for &(format, value, want) in cases::CASES {
        f.set_format_str(1, format).unwrap();
        match f.format(1, value) {
            Ok(got) if got == want => {}
            got => failures.push(format!(
                "{format:?} of {value:?}: got {got:?}, C gives {want:?}"
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}
